import {t} from './i18n.js?v=pokerinno-balloons-v1';
import {readMessagePreferences,messageTypes,buildPokerinnoMessages} from './pokerinno-messages.js?v=pokerinno-balloons-v1';
export function messageSettings(storage){const preferences=readMessagePreferences(storage);return `<section class="pokerinno-message-settings"><div class="section-top"><h2>${t('messages.settings')}</h2></div><p>${t('messages.settingsDescription')}</p>${messageTypes.map(type=>`<div class="setting"><div><h3>${t('messages.option.'+type)}</h3><p>${t('messages.optionDescription.'+type)}</p></div><input type="checkbox" data-message-preference="${type}" aria-label="${t('messages.option.'+type)}" ${preferences[type]?'checked':''}></div>`).join('')}</section>`}
export function closePokerinno(){document.querySelector('#pokerinno-balloons')?.remove()}
export function showPokerinno({storage,activities,pending,absent}){
 closePokerinno();const messages=buildPokerinnoMessages({preferences:readMessagePreferences(storage),activities,pending,absent});
 const region=document.createElement('aside');region.id='pokerinno-balloons';region.className='pokerinno-balloons';region.setAttribute('role','region');region.setAttribute('aria-label',t('messages.title'));document.body.append(region);let index=0;
 const paint=()=>{const message=messages[index];region.innerHTML=`<button class="pokerinno-dismiss" aria-label="${t('messages.close')}">×</button>${message?`<div class="pokerinno-speech-row"><img class="pokerinno-speaker" src="assets/pokerinno-${message.mood}.webp" alt="Pokerinno"><div class="pokerinno-speech"><strong>POKERINNO</strong><p aria-live="polite">${t(message.key,message.params)}</p><a class="primary" href="${message.href}" data-pokerinno-action>${t(message.action)}</a></div></div><div class="pokerinno-speech-controls"><span>${index+1} / ${messages.length}</span>${messages.length>1?`<button class="quiet" data-pokerinno-next>${t('messages.next')}</button>`:''}<a class="quiet" href="#profile" data-pokerinno-action>${t('messages.settings')}</a></div>`:`<p>${t('messages.disabled')}</p><a class="quiet" href="#profile" data-pokerinno-action>${t('messages.settings')}</a>`}`;region.querySelector('.pokerinno-dismiss').onclick=closePokerinno;region.querySelector('[data-pokerinno-next]')?.addEventListener('click',()=>{index=(index+1)%messages.length;paint()});region.querySelectorAll('[data-pokerinno-action]').forEach(a=>a.addEventListener('click',closePokerinno))};
 paint();
}
document.addEventListener('keydown',e=>{if(e.key==='Escape')closePokerinno()});
